import{at as e,it as t,n,vt as r}from"./chunks/framework.BFgrh0AM.js";var i=JSON.parse(`{"title":"Class: Item","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/Item.md","filePath":"api/@jsprismarine/prismarine/classes/Item.md"}`),a={name:`api/@jsprismarine/prismarine/classes/Item.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / Item</p><h1 id="class-item" tabindex="-1">Class: Item <a class="header-anchor" href="#class-item" aria-label="Permalink to “Class: Item”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L141" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:141</a></p><p>One item stack, as the rest of the server holds one.</p><p>Everything it answers about itself - how hard it hits, how much armor it is worth, how much durability it has, what it harvests - is read off Java&#39;s data components rather than declared by a subclass. The 65 item classes this replaced each restated one or two of those numbers; the table has all of them, for all 1613 items.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new Item</strong>(<code>__namedParameters</code>): <code>Item</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L199" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:199</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="namedparameters" tabindex="-1">__namedParameters <a class="header-anchor" href="#namedparameters" aria-label="Permalink to “__namedParameters”">​</a></h5><p><a href="./../#itemprops"><code>ItemProps</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Item</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="count" tabindex="-1">count <a class="header-anchor" href="#count" aria-label="Permalink to “count”">​</a></h3><blockquote><p><strong>count</strong>: <code>number</code> = <code>1</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L151" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:151</a></p><hr><h3 id="durability" tabindex="-1">durability <a class="header-anchor" href="#durability" aria-label="Permalink to “durability”">​</a></h3><blockquote><p><strong>durability</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L147" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:147</a></p><hr><h3 id="meta" tabindex="-1">meta <a class="header-anchor" href="#meta" aria-label="Permalink to “meta”">​</a></h3><blockquote><p><strong>meta</strong>: <code>number</code> = <code>0</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L146" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:146</a></p><hr><h3 id="nbt" tabindex="-1">nbt <a class="header-anchor" href="#nbt" aria-label="Permalink to “nbt”">​</a></h3><blockquote><p><strong>nbt</strong>: <code>null</code> = <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L150" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:150</a></p><hr><h3 id="stacknetworkid" tabindex="-1">stackNetworkId <a class="header-anchor" href="#stacknetworkid" aria-label="Permalink to “stackNetworkId”">​</a></h3><blockquote><p><strong>stackNetworkId</strong>: <code>number</code> = <code>0</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L164" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:164</a></p><p>The stack network id the client knows this stack by, or 0 before it has one.</p><p>The inventory packets write it, so that a client and the server name a stack by the same number in an <code>ItemStackRequest</code> and in its answer. A stack read off the wire keeps the id it came with.</p><p>Ids are counted per player by <code>HumanInventory.assignStackNetworkId</code>. A stack keeps its id when it moves whole or changes size through <a href="#withcount">Item.withCount</a>; every other copy starts without one, and so does a part split off a stack.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="aspredicatestack" tabindex="-1">asPredicateStack() <a class="header-anchor" href="#aspredicatestack" aria-label="Permalink to “asPredicateStack()”">​</a></h3><blockquote><p><strong>asPredicateStack</strong>(): <a href="./../../predicates/#itemstack"><code>ItemStack</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L616" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:616</a></p><p>This stack as the loot, predicate and enchantment grammars read one.</p><p>The components carry what those grammars actually look at today: <code>minecraft:enchantments</code> for Fortune, Looting, Silk Touch and every effect component, and the three the item type declares that the enchanting table and the anvil read off a stack - <code>minecraft:enchantable</code>, <code>minecraft:max_damage</code> and <code>minecraft:damage</code>. An empty map used to go out here, which made every <code>apply_bonus</code> see an unenchanted tool and every enchanting table refuse every item.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../predicates/#itemstack"><code>ItemStack</code></a></p><hr><h3 id="getamount" tabindex="-1">getAmount() <a class="header-anchor" href="#getamount" aria-label="Permalink to “getAmount()”">​</a></h3><blockquote><p><strong>getAmount</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L532" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:532</a></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getarmordefensepoints" tabindex="-1">getArmorDefensePoints() <a class="header-anchor" href="#getarmordefensepoints" aria-label="Permalink to “getArmorDefensePoints()”">​</a></h3><blockquote><p><strong>getArmorDefensePoints</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L370" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:370</a></p><p>The armor points the item is worth while worn.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getarmortoughness" tabindex="-1">getArmorToughness() <a class="header-anchor" href="#getarmortoughness" aria-label="Permalink to “getArmorToughness()”">​</a></h3><blockquote><p><strong>getArmorToughness</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L375" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:375</a></p><p>The armor toughness the item is worth while worn.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getattackdamage" tabindex="-1">getAttackDamage() <a class="header-anchor" href="#getattackdamage" aria-label="Permalink to “getAttackDamage()”">​</a></h3><blockquote><p><strong>getAttackDamage</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L365" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:365</a></p><p>Half-hearts a swing with this in hand is worth.</p><p>The player&#39;s own base of one, plus the item&#39;s <code>minecraft:base_attack_damage</code> modifier. A bare fist and a torch are both worth one, which is vanilla&#39;s rule rather than a placeholder.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getblockruntimeid" tabindex="-1">getBlockRuntimeId() <a class="header-anchor" href="#getblockruntimeid" aria-label="Permalink to “getBlockRuntimeId()”">​</a></h3><blockquote><p><strong>getBlockRuntimeId</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L728" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:728</a></p><p>The runtime id of the block this item places, or zero for anything that places none.</p><p>An id given at construction wins. Otherwise the name resolves to the block&#39;s default state, which is right for a stack a player holds and wrong for two kinds of creative entry: a block the menu shows in another state (a piston faces up there), and the item form of a block vanilla treats as a plain item (a door, a bed, a hanging sign travel with a zero) while this server has a block schema under the same name.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>the hashed block runtime id, or <code>0</code>.</p><hr><h3 id="getburntime" tabindex="-1">getBurnTime() <a class="header-anchor" href="#getburntime" aria-label="Permalink to “getBurnTime()”">​</a></h3><blockquote><p><strong>getBurnTime</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L353" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:353</a></p><p>How long the item burns in a furnace, in ticks.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getcandestroyblocks" tabindex="-1">getCanDestroyBlocks() <a class="header-anchor" href="#getcandestroyblocks" aria-label="Permalink to “getCanDestroyBlocks()”">​</a></h3><blockquote><p><strong>getCanDestroyBlocks</strong>(): readonly <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L424" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:424</a></p><p>The Bedrock block identifiers this stack may destroy.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>string</code>[]</p><hr><h3 id="getcanplaceonblocks" tabindex="-1">getCanPlaceOnBlocks() <a class="header-anchor" href="#getcanplaceonblocks" aria-label="Permalink to “getCanPlaceOnBlocks()”">​</a></h3><blockquote><p><strong>getCanPlaceOnBlocks</strong>(): readonly <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L419" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:419</a></p><p>The Bedrock block identifiers this stack may be placed on.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>string</code>[]</p><hr><h3 id="getcontents" tabindex="-1">getContents() <a class="header-anchor" href="#getcontents" aria-label="Permalink to “getContents()”">​</a></h3><blockquote><p><strong>getContents</strong>(): readonly (<code>Item</code> | <code>null</code>)[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L414" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:414</a></p><p>What this stack holds inside it, one entry per slot and null for an empty one.</p><p>Empty for everything but a container item, which today is the shulker box.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p>readonly (<code>Item</code> | <code>null</code>)[]</p><hr><h3 id="getcustomname" tabindex="-1">getCustomName() <a class="header-anchor" href="#getcustomname" aria-label="Permalink to “getCustomName()”">​</a></h3><blockquote><p><strong>getCustomName</strong>(): <code>string</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L400" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:400</a></p><p>The name an anvil gave this stack, or undefined when it still has the item&#39;s own.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code> | <code>undefined</code></p><hr><h3 id="getdurability" tabindex="-1">getDurability() <a class="header-anchor" href="#getdurability" aria-label="Permalink to “getDurability()”">​</a></h3><blockquote><p><strong>getDurability</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L524" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:524</a></p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getenchantmentlevel" tabindex="-1">getEnchantmentLevel() <a class="header-anchor" href="#getenchantmentlevel" aria-label="Permalink to “getEnchantmentLevel()”">​</a></h3><blockquote><p><strong>getEnchantmentLevel</strong>(<code>enchantment</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L395" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:395</a></p><p>The level of one enchantment, or zero when the stack does not carry it.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="enchantment" tabindex="-1">enchantment <a class="header-anchor" href="#enchantment" aria-label="Permalink to “enchantment”">​</a></h5><p><code>string</code></p><p>A namespaced or bare Java enchantment id.</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getenchantments" tabindex="-1">getEnchantments() <a class="header-anchor" href="#getenchantments" aria-label="Permalink to “getEnchantments()”">​</a></h3><blockquote><p><strong>getEnchantments</strong>(): <code>ReadonlyMap</code>&lt;<code>string</code>, <code>number</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L386" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:386</a></p><p>The stack&#39;s enchantments, by namespaced Java id.</p><p>Java ids and not Bedrock ones, because the enchantment definitions, the loot tables and the effect components are all Java&#39;s and converting at every read would mean converting back to run any of them.</p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>ReadonlyMap</code>&lt;<code>string</code>, <code>number</code>&gt;</p><hr><h3 id="getequipmentslot" tabindex="-1">getEquipmentSlot() <a class="header-anchor" href="#getequipmentslot" aria-label="Permalink to “getEquipmentSlot()”">​</a></h3><blockquote><p><strong>getEquipmentSlot</strong>(): <code>string</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L348" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:348</a></p><p>Where <code>minecraft:equippable</code> says this item is worn.</p><p>The game&#39;s own answer to which slot an item occupies, which is what dressing a mob from a loot table needs: the table names <code>minecraft:iron_helmet</code> and nothing else says it is a helmet. One of <code>@jsprismarine/items</code>&#39; <code>EQUIPMENT_SLOTS</code>.</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code> | <code>undefined</code></p><p>The slot name, or undefined for an item that is not worn, which a sword and a bow are.</p><hr><h3 id="getjavatags" tabindex="-1">getJavaTags() <a class="header-anchor" href="#getjavatags" aria-label="Permalink to “getJavaTags()”">​</a></h3><blockquote><p><strong>getJavaTags</strong>(): readonly <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L245" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:245</a></p><p>The Java datapack tags attached to this Bedrock item type.</p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>string</code>[]</p><hr><h3 id="getlore" tabindex="-1">getLore() <a class="header-anchor" href="#getlore" aria-label="Permalink to “getLore()”">​</a></h3><blockquote><p><strong>getLore</strong>(): readonly <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L405" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:405</a></p><p>The lore lines on this stack, which is an empty array for most of them.</p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>string</code>[]</p><hr><h3 id="getmaxamount" tabindex="-1">getMaxAmount() <a class="header-anchor" href="#getmaxamount" aria-label="Permalink to “getMaxAmount()”">​</a></h3><blockquote><p><strong>getMaxAmount</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L528" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:528</a></p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getmaxdurability" tabindex="-1">getMaxDurability() <a class="header-anchor" href="#getmaxdurability" aria-label="Permalink to “getMaxDurability()”">​</a></h3><blockquote><p><strong>getMaxDurability</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L520" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:520</a></p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getmeta" tabindex="-1">getMeta() <a class="header-anchor" href="#getmeta" aria-label="Permalink to “getMeta()”">​</a></h3><blockquote><p><strong>getMeta</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L286" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:286</a></p><p>The stack&#39;s damage or variant value, which the wire carries beside the id.</p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getminingspeed" tabindex="-1">getMiningSpeed() <a class="header-anchor" href="#getminingspeed" aria-label="Permalink to “getMiningSpeed()”">​</a></h3><blockquote><p><strong>getMiningSpeed</strong>(<code>block</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L585" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:585</a></p><p>How fast this mines one block, which is Java&#39;s <code>Player.getDestroySpeed</code> as far as a stack alone can answer it.</p><p>The <code>minecraft:tool</code> rules give the base - the first rule whose block set matches and that states a speed - and <code>minecraft:mining_efficiency</code> raises it, which is the attribute Efficiency&#39;s modifier writes. Java only adds the attribute to a speed already above one, so Efficiency does nothing for a tool that is the wrong tool for the block.</p><p>Dig Speed, Mining Fatigue, being underwater without Aqua Affinity and being off the ground are the four other terms of Java&#39;s formula, and none of them is modeled: there is no effect system and no swimming state on an entity.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="block" tabindex="-1">block <a class="header-anchor" href="#block" aria-label="Permalink to “block”">​</a></h5><p><code>string</code></p><p>The block identifier being mined.</p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>A multiplier on the base rate; 1 for a bare hand or an item with no rule for the block, which is Java&#39;s <code>Item.getDestroySpeed</code>.</p><hr><h3 id="getname" tabindex="-1">getName() <a class="header-anchor" href="#getname" aria-label="Permalink to “getName()”">​</a></h3><blockquote><p><strong>getName</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L230" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:230</a></p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getruntimeid" tabindex="-1">getRuntimeId() <a class="header-anchor" href="#getruntimeid" aria-label="Permalink to “getRuntimeId()”">​</a></h3><blockquote><p><strong>getRuntimeId</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L272" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:272</a></p><p>The Bedrock runtime id for this item under the canonical numbering, protocol 2193&#39;s.</p><p>What everything off the wire means by an item&#39;s number. A stack going to a client is numbered by Item.wireId against that session&#39;s own table instead, because the two disagree for 82 items from 1.26.60 on.</p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="gettags" tabindex="-1">getTags() <a class="header-anchor" href="#gettags" aria-label="Permalink to “getTags()”">​</a></h3><blockquote><p><strong>getTags</strong>(): readonly <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L235" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:235</a></p><p>The Bedrock tags attached to this item type, or an empty list when it has no type.</p><h4 id="returns-24" tabindex="-1">Returns <a class="header-anchor" href="#returns-24" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>string</code>[]</p><hr><h3 id="harvests" tabindex="-1">harvests() <a class="header-anchor" href="#harvests" aria-label="Permalink to “harvests()”">​</a></h3><blockquote><p><strong>harvests</strong>(<code>block</code>, <code>content?</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L553" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:553</a></p><p>Whether swinging this harvests a block rather than destroying it for nothing.</p><p>Java&#39;s <code>minecraft:tool</code> rules in one pass: the first rule whose block set matches and whose <code>correct_for_drops</code> is stated decides, which is how <code>#minecraft:incorrect_for_stone_tool</code> stops a stone pickaxe mining diamond while <code>#minecraft:mineable/pickaxe</code> lets it mine stone.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="block-1" tabindex="-1">block <a class="header-anchor" href="#block-1" aria-label="Permalink to “block”">​</a></h5><p><code>string</code></p><p>The block identifier being mined.</p><h5 id="content" tabindex="-1">content? <a class="header-anchor" href="#content" aria-label="Permalink to “content?”">​</a></h5><p><a href="./../#servercontent"><code>ServerContent</code></a> | <code>undefined</code> = <code>...</code></p><p>The content whose merged tags resolve this rule, defaulting to this stack&#39;s content.</p><h4 id="returns-25" tabindex="-1">Returns <a class="header-anchor" href="#returns-25" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>False for a bare name no rule covers, which is Java&#39;s answer too.</p><hr><h3 id="hascomponent" tabindex="-1">hasComponent() <a class="header-anchor" href="#hascomponent" aria-label="Permalink to “hasComponent()”">​</a></h3><blockquote><p><strong>hasComponent</strong>(<code>name</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L261" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:261</a></p><p>Whether the resolved item type declares the named data component.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><h4 id="returns-26" tabindex="-1">Returns <a class="header-anchor" href="#returns-26" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="hasenchantment" tabindex="-1">hasEnchantment() <a class="header-anchor" href="#hasenchantment" aria-label="Permalink to “hasEnchantment()”">​</a></h3><blockquote><p><strong>hasEnchantment</strong>(<code>enchantment</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L516" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:516</a></p><p>Whether the stack carries an enchantment at any level.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="enchantment-1" tabindex="-1">enchantment <a class="header-anchor" href="#enchantment-1" aria-label="Permalink to “enchantment”">​</a></h5><p><code>string</code></p><p>A namespaced or bare Java enchantment id. This took <code>ItemEnchantmentType</code> and always answered false; the enum numbers Bedrock&#39;s 37 enchantments, gives two of them the same number, and has nothing to say about the other six or about a datapack&#39;s.</p><h4 id="returns-27" tabindex="-1">Returns <a class="header-anchor" href="#returns-27" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="hasjavatag" tabindex="-1">hasJavaTag() <a class="header-anchor" href="#hasjavatag" aria-label="Permalink to “hasJavaTag()”">​</a></h3><blockquote><p><strong>hasJavaTag</strong>(<code>tag</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L254" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:254</a></p><p>Whether a Java datapack tag includes this item type.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tag" tabindex="-1">tag <a class="header-anchor" href="#tag" aria-label="Permalink to “tag”">​</a></h5><p><code>string</code></p><h4 id="returns-28" tabindex="-1">Returns <a class="header-anchor" href="#returns-28" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="hastag" tabindex="-1">hasTag() <a class="header-anchor" href="#hastag" aria-label="Permalink to “hasTag()”">​</a></h3><blockquote><p><strong>hasTag</strong>(<code>tag</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L240" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:240</a></p><p>Whether this item type carries one of its Bedrock tags.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tag-1" tabindex="-1">tag <a class="header-anchor" href="#tag-1" aria-label="Permalink to “tag”">​</a></h5><p><code>string</code></p><h4 id="returns-29" tabindex="-1">Returns <a class="header-anchor" href="#returns-29" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="isarmorpiece" tabindex="-1">isArmorPiece() <a class="header-anchor" href="#isarmorpiece" aria-label="Permalink to “isArmorPiece()”">​</a></h3><blockquote><p><strong>isArmorPiece</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L335" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:335</a></p><p>Whether the item&#39;s components give it an armor value.</p><h4 id="returns-30" tabindex="-1">Returns <a class="header-anchor" href="#returns-30" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="ispartofcreativeinventory" tabindex="-1">isPartOfCreativeInventory() <a class="header-anchor" href="#ispartofcreativeinventory" aria-label="Permalink to “isPartOfCreativeInventory()”">​</a></h3><blockquote><p><strong>isPartOfCreativeInventory</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L536" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:536</a></p><h4 id="returns-31" tabindex="-1">Returns <a class="header-anchor" href="#returns-31" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="istool" tabindex="-1">isTool() <a class="header-anchor" href="#istool" aria-label="Permalink to “isTool()”">​</a></h3><blockquote><p><strong>isTool</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L330" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:330</a></p><p>Whether the item&#39;s components make it a tool.</p><h4 id="returns-32" tabindex="-1">Returns <a class="header-anchor" href="#returns-32" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="networkserialize" tabindex="-1">networkSerialize() <a class="header-anchor" href="#networkserialize" aria-label="Permalink to “networkSerialize()”">​</a></h3><blockquote><p><strong>networkSerialize</strong>(<code>stream</code>, <code>stackNetId?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L670" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:670</a></p><p>Writes an item stack in the form that carries a stack net id - an <code>ItemInstance</code>.</p><p>There are two forms on the wire, and at 2168 they no longer differ by one byte. This one, which an inventory, an equipped hand or a transaction carries, opens with a <strong>fixed two byte id</strong> and closes with an <em>unsigned</em> block runtime id; the other, <a href="#networkserializewithoutstackid">networkSerializeWithoutStackId</a>, uses a varint for both. Neither still stops early for air: up to 748 a zero id was the whole stack, and now every field is written whatever the id is. An inventory is mostly empty slots, so a stack that stops after the id truncates the packet almost immediately - which is exactly what the client reports as a bad packet on join, before any of the interesting packets are even reached.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="stream" tabindex="-1">stream <a class="header-anchor" href="#stream" aria-label="Permalink to “stream”">​</a></h5><p><a href="./../../binaryutils/classes/BinaryStream.html"><code>BinaryStream</code></a></p><p>the stream to write to.</p><h5 id="stacknetid" tabindex="-1">stackNetId? <a class="header-anchor" href="#stacknetid" aria-label="Permalink to “stackNetId?”">​</a></h5><p><code>number</code> | <code>null</code> = <code>null</code></p><p>the stack&#39;s net id, when the receiver tracks one.</p><h4 id="returns-33" tabindex="-1">Returns <a class="header-anchor" href="#returns-33" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="see" tabindex="-1">See <a class="header-anchor" href="#see" aria-label="Permalink to “See”">​</a></h4><p><a href="https://mojang.github.io/bedrock-protocol-docs/1.26.51/types/network-item-stack-descriptor/" target="_blank" rel="noreferrer">https://mojang.github.io/bedrock-protocol-docs/1.26.51/types/network-item-stack-descriptor/</a></p><hr><h3 id="networkserializewithoutstackid" tabindex="-1">networkSerializeWithoutStackId() <a class="header-anchor" href="#networkserializewithoutstackid" aria-label="Permalink to “networkSerializeWithoutStackId()”">​</a></h3><blockquote><p><strong>networkSerializeWithoutStackId</strong>(<code>stream</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L707" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:707</a></p><p>Writes an item stack in the form that carries no stack net id - an <code>ItemStack</code>.</p><p>What the creative menu and every recipe carries, because nothing is tracking these stacks. See <a href="#networkserialize">networkSerialize</a> for how the two forms differ beyond the flag.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="stream-1" tabindex="-1">stream <a class="header-anchor" href="#stream-1" aria-label="Permalink to “stream”">​</a></h5><p><a href="./../../binaryutils/classes/BinaryStream.html"><code>BinaryStream</code></a></p><h4 id="returns-34" tabindex="-1">Returns <a class="header-anchor" href="#returns-34" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="tostackdescriptor" tabindex="-1">toStackDescriptor() <a class="header-anchor" href="#tostackdescriptor" aria-label="Permalink to “toStackDescriptor()”">​</a></h3><blockquote><p><strong>toStackDescriptor</strong>(<code>source</code>, <code>stackNetId?</code>): <a href="./../../protocol/#itemstackdescriptordata"><code>ItemStackDescriptorData</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L684" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:684</a></p><p>This stack as the six wire fields of a <code>NetworkItemStackDescriptor</code>.</p><p>The server converts its game item into this protocol DTO at the package boundary; the protocol package writes the bytes. An empty stack zeroes every field after the id, as <a href="#networkserialize">networkSerialize</a> always has.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="source" tabindex="-1">source <a class="header-anchor" href="#source" aria-label="Permalink to “source”">​</a></h5><p><a href="./../../binaryutils/classes/BinaryStream.html"><code>BinaryStream</code></a> | <a href="./../../protocol/#protocolcontext"><code>ProtocolContext</code></a></p><p>The packet stream or negotiated protocol context that selects item numbering.</p><h5 id="stacknetid-1" tabindex="-1">stackNetId? <a class="header-anchor" href="#stacknetid-1" aria-label="Permalink to “stackNetId?”">​</a></h5><p><code>number</code> | <code>null</code> = <code>null</code></p><p>The stack&#39;s net id, when the receiver tracks one.</p><h4 id="returns-35" tabindex="-1">Returns <a class="header-anchor" href="#returns-35" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../protocol/#itemstackdescriptordata"><code>ItemStackDescriptorData</code></a></p><p>The descriptor the stack goes out as.</p><hr><h3 id="userdatatag" tabindex="-1">userDataTag() <a class="header-anchor" href="#userdatatag" aria-label="Permalink to “userDataTag()”">​</a></h3><blockquote><p><strong>userDataTag</strong>(): <a href="./../../nbt/classes/NBTTagCompound.html"><code>NBTTagCompound</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L739" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:739</a></p><p>What the client is told about this stack beyond its id, count and aux value.</p><p>The enchantments, the name, the lore and the durability spent, in the shape itemUserDataTag lays out. Null for a stack with none of them and no durability, which is most of them and every slot of an untouched inventory.</p><h4 id="returns-36" tabindex="-1">Returns <a class="header-anchor" href="#returns-36" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../nbt/classes/NBTTagCompound.html"><code>NBTTagCompound</code></a> | <code>null</code></p><hr><h3 id="withcontents" tabindex="-1">withContents() <a class="header-anchor" href="#withcontents" aria-label="Permalink to “withContents()”">​</a></h3><blockquote><p><strong>withContents</strong>(<code>contents</code>): <code>Item</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L433" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:433</a></p><p>A copy of this stack holding different contents.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="contents" tabindex="-1">contents <a class="header-anchor" href="#contents" aria-label="Permalink to “contents”">​</a></h5><p>readonly (<code>Item</code> | <code>null</code>)[]</p><p>One entry per slot, null for an empty one.</p><h4 id="returns-37" tabindex="-1">Returns <a class="header-anchor" href="#returns-37" aria-label="Permalink to “Returns”">​</a></h4><p><code>Item</code></p><hr><h3 id="withcount" tabindex="-1">withCount() <a class="header-anchor" href="#withcount" aria-label="Permalink to “withCount()”">​</a></h3><blockquote><p><strong>withCount</strong>(<code>count</code>): <code>Item</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L480" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:480</a></p><p>A copy of this stack holding a different number of items.</p><p>Everything else comes along: the enchantments, the durability spent, the name, the lore, the contents and the content the stack reads its components from. A slot that changes size goes through here, because the wire writes the item&#39;s count and not the slot&#39;s.</p><p>The stack network id comes along too, because a stack that grows or shrinks is still the stack the client knows: a Bedrock Dedicated Server 1.26.52 keeps the id on what is left of a stack and on a stack merged onto. A part split off is a new stack, and the caller clears the id on it.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="count-1" tabindex="-1">count <a class="header-anchor" href="#count-1" aria-label="Permalink to “count”">​</a></h5><p><code>number</code></p><p>How many the copy holds. Set after construction, so zero stays zero.</p><h4 id="returns-38" tabindex="-1">Returns <a class="header-anchor" href="#returns-38" aria-label="Permalink to “Returns”">​</a></h4><p><code>Item</code></p><hr><h3 id="withdisplay" tabindex="-1">withDisplay() <a class="header-anchor" href="#withdisplay" aria-label="Permalink to “withDisplay()”">​</a></h3><blockquote><p><strong>withDisplay</strong>(<code>customName</code>, <code>lore?</code>): <code>Item</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L462" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:462</a></p><p>A copy of this stack with a different name and lore.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="customname" tabindex="-1">customName <a class="header-anchor" href="#customname" aria-label="Permalink to “customName”">​</a></h5><p><code>string</code> | <code>undefined</code></p><p>The new name, or undefined to go back to the item&#39;s own.</p><h5 id="lore" tabindex="-1">lore? <a class="header-anchor" href="#lore" aria-label="Permalink to “lore?”">​</a></h5><p>readonly <code>string</code>[] = <code>...</code></p><h4 id="returns-39" tabindex="-1">Returns <a class="header-anchor" href="#returns-39" aria-label="Permalink to “Returns”">​</a></h4><p><code>Item</code></p><hr><h3 id="withenchantments" tabindex="-1">withEnchantments() <a class="header-anchor" href="#withenchantments" aria-label="Permalink to “withEnchantments()”">​</a></h3><blockquote><p><strong>withEnchantments</strong>(<code>levels</code>): <code>Item</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L453" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:453</a></p><p>A copy of this stack carrying a different enchantment set.</p><p>A copy rather than a mutation: the anvil and the enchanting table both compute a result before the player has paid for it, and a stack enchanted in place would have been enchanted whether they paid or not.</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="levels" tabindex="-1">levels <a class="header-anchor" href="#levels" aria-label="Permalink to “levels”">​</a></h5><p><code>ReadonlyMap</code>&lt;<code>string</code>, <code>number</code>&gt; | <code>Readonly</code>&lt;<code>Record</code>&lt;<code>string</code>, <code>number</code>&gt;&gt;</p><h4 id="returns-40" tabindex="-1">Returns <a class="header-anchor" href="#returns-40" aria-label="Permalink to “Returns”">​</a></h4><p><code>Item</code></p><hr><h3 id="withmeta" tabindex="-1">withMeta() <a class="header-anchor" href="#withmeta" aria-label="Permalink to “withMeta()”">​</a></h3><blockquote><p><strong>withMeta</strong>(<code>meta</code>): <code>Item</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L442" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:442</a></p><p>A copy of this stack with a different legacy auxiliary value.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="meta-1" tabindex="-1">meta <a class="header-anchor" href="#meta-1" aria-label="Permalink to “meta”">​</a></h5><p><code>number</code></p><p>The replacement auxiliary value, such as a transformed entity-interaction item.</p><h4 id="returns-41" tabindex="-1">Returns <a class="header-anchor" href="#returns-41" aria-label="Permalink to “Returns”">​</a></h4><p><code>Item</code></p><hr><h3 id="air" tabindex="-1">air() <a class="header-anchor" href="#air" aria-label="Permalink to “air()”">​</a></h3><blockquote><p><code>static</code> <strong>air</strong>(): <code>Item</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L640" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:640</a></p><p>The empty stack.</p><p>A count of zero as well as the air name, because at 2168 an empty stack still writes its count - so an &quot;empty&quot; stack holding one of something says the slot has one air in it.</p><h4 id="returns-42" tabindex="-1">Returns <a class="header-anchor" href="#returns-42" aria-label="Permalink to “Returns”">​</a></h4><p><code>Item</code></p><hr><h3 id="fromstackdescriptor" tabindex="-1">fromStackDescriptor() <a class="header-anchor" href="#fromstackdescriptor" aria-label="Permalink to “fromStackDescriptor()”">​</a></h3><blockquote><p><code>static</code> <strong>fromStackDescriptor</strong>(<code>source</code>, <code>descriptor</code>): <code>Item</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L821" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:821</a></p><p>The stack a <code>NetworkItemStackDescriptor</code> describes.</p><p>Resolves the wire descriptor returned by a protocol packet into the server&#39;s game item.</p><h4 id="parameters-16" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-16" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="source-1" tabindex="-1">source <a class="header-anchor" href="#source-1" aria-label="Permalink to “source”">​</a></h5><p><a href="./../../binaryutils/classes/BinaryStream.html"><code>BinaryStream</code></a> | <a href="./../../protocol/#protocolcontext"><code>ProtocolContext</code></a></p><p>The packet stream or negotiated protocol context that selects item numbering.</p><h5 id="descriptor" tabindex="-1">descriptor <a class="header-anchor" href="#descriptor" aria-label="Permalink to “descriptor”">​</a></h5><p><a href="./../../protocol/#itemstackdescriptordata"><code>ItemStackDescriptorData</code></a></p><p>The six wire fields.</p><h4 id="returns-43" tabindex="-1">Returns <a class="header-anchor" href="#returns-43" aria-label="Permalink to “Returns”">​</a></h4><p><code>Item</code></p><p>The stack, with an unknown id kept so it goes back out as the client sent it.</p><hr><h3 id="networkdeserialize" tabindex="-1">networkDeserialize() <a class="header-anchor" href="#networkdeserialize" aria-label="Permalink to “networkDeserialize()”">​</a></h3><blockquote><p><code>static</code> <strong>networkDeserialize</strong>(<code>stream</code>): <code>Item</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L809" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:809</a></p><p>Reads an item stack off the wire.</p><p>The layout is <code>NetworkItemStackDescriptor</code>, which <code>@jsprismarine/protocol</code> already describes: the id, the count, the aux value, an <strong>always present</strong> flag saying whether a stack net id follows, the block runtime id, and one length prefixed blob holding the nbt and the can-place-on / can-break lists. All of it, even for air.</p><p>The block lists are retained so a stack the client sends can be sent back with the same adventure-mode restrictions. The NBT compound and optional shield blocking tick remain unused here; the user-data structure isolates them from the following packet fields.</p><p>Reading the flag is what keeps every field after it aligned. It used to be read only when a caller asked for <code>extra</code>, which no caller ever did, so from that byte onwards the reader was one out: the lists it then walked had garbage lengths, ran off the end of the buffer and threw. Every InventoryTransaction died there - which is what left a survival block break with no sound, the packet never reaching its handler.</p><h4 id="parameters-17" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-17" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="stream-2" tabindex="-1">stream <a class="header-anchor" href="#stream-2" aria-label="Permalink to “stream”">​</a></h5><p><a href="./../../binaryutils/classes/BinaryStream.html"><code>BinaryStream</code></a></p><h4 id="returns-44" tabindex="-1">Returns <a class="header-anchor" href="#returns-44" aria-label="Permalink to “Returns”">​</a></h4><p><code>Item</code></p><h4 id="see-1" tabindex="-1">See <a class="header-anchor" href="#see-1" aria-label="Permalink to “See”">​</a></h4><p><a href="https://mojang.github.io/bedrock-protocol-docs/1.26.51/types/network-item-stack-descriptor/" target="_blank" rel="noreferrer">https://mojang.github.io/bedrock-protocol-docs/1.26.51/types/network-item-stack-descriptor/</a></p><hr><h3 id="networkdeserializewithoutstackid" tabindex="-1">networkDeserializeWithoutStackId() <a class="header-anchor" href="#networkdeserializewithoutstackid" aria-label="Permalink to “networkDeserializeWithoutStackId()”">​</a></h3><blockquote><p><code>static</code> <strong>networkDeserializeWithoutStackId</strong>(<code>stream</code>): <code>Item</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/73efe0da742b65ad1548501d913b6613463f738e/packages/prismarine/src/item/Item.ts#L859" target="_blank" rel="noreferrer">prismarine/src/item/Item.ts:859</a></p><p>Reads the form that carries no stack net id - the creative menu&#39;s.</p><p>The counterpart to <a href="#networkserializewithoutstackid">networkSerializeWithoutStackId</a>; see it for why the two forms exist and what confusing them costs.</p><h4 id="parameters-18" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-18" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="stream-3" tabindex="-1">stream <a class="header-anchor" href="#stream-3" aria-label="Permalink to “stream”">​</a></h5><p><a href="./../../binaryutils/classes/BinaryStream.html"><code>BinaryStream</code></a></p><h4 id="returns-45" tabindex="-1">Returns <a class="header-anchor" href="#returns-45" aria-label="Permalink to “Returns”">​</a></h4><p><code>Item</code></p>`,458)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};